1357:                             return normalize(vec3(h0 - hx, eps, h0 - hz));
1358:                         }
1359: 
1360:                         void main() {
1361:                             if (vDepth <= 0.005) discard;
1362: 
1363:                             vec3 viewVec = normalize(cameraPosition - vWorldPos);
1364:                             vec3 normal = uQuality > 0.5
1365:                                 ? getWaveNormal(vWorldPos.xz, uTime)
1366:                                 : vec3(0.0, 1.0, 0.0);
1367: 
1368:                             // Schlick Fresnel approximation
1369:                             float cosTheta = clamp(dot(viewVec, normal), 0.0, 1.0);
1370:                             float fresnel = 0.03 + 0.97 * pow(1.0 - cosTheta, 4.2);
1371: 
1372:                             // Beer-Lambert depth absorption (crystal turquoise shallows -> deep emerald-teal)
1373:                             vec3 shallowColor = vec3(0.14, 0.48, 0.46);
1374:                             vec3 deepColor = vec3(0.02, 0.12, 0.16);
1375:                             float depthFactor = 1.0 - exp(-vDepth * 0.68);
1376:                             vec3 waterBody = mix(shallowColor, deepColor, depthFactor);
1377: 
1378:                             // Animated underwater caustic shimmer in shallow water
1379:                             if (uQuality > 0.5 && vDepth < 2.6) {
1380:                                 float c1 = sin(vWorldPos.x * 2.6 + uTime * 2.2) * cos(vWorldPos.z * 2.6 - uTime * 1.8);
1381:                                 float c2 = sin((vWorldPos.x - vWorldPos.z) * 3.8 + uTime * 2.9);
1382:                                 float caustics = pow(clamp((c1 + c2) * 0.5 + 0.5, 0.0, 1.0), 4.0);
1383:                                 float shallowMask = 1.0 - clamp(vDepth / 2.6, 0.0, 1.0);
1384:                                 waterBody += vec3(0.18, 0.34, 0.30) * caustics * shallowMask * 0.65;
1385:                             }
1386: 
1387:                             // Sky reflection & crisp sun specular glints
1388:                             vec3 reflColor = mix(uSkyColor * 0.72, uSkyColor, 0.5);
1389:                             vec3 color = mix(waterBody, reflColor, fresnel * 0.85);
1390: 
1391:                             vec3 halfVec = normalize(normalize(uSunDir) + viewVec);
1392:                             float specPower = uQuality > 0.5 ? 240.0 : 60.0;
1393:                             float spec = pow(max(dot(normal, halfVec), 0.0), specPower);
1394:                             color += uSunColor * spec * (uQuality > 0.5 ? 2.4 : 0.8);
1395: 
1396:                             // Animated white shoreline foam where water meets land
1397:                             float alpha = clamp(vDepth * 2.8, 0.25, 0.94);
1398:                             if (uQuality > 0.5 && vDepth < 0.42) {
1399:                                 float foamWave = sin(vDepth * 26.0 - uTime * 3.2 + sin(vWorldPos.x * 1.7 + vWorldPos.z * 1.5) * 2.0);
1400:                                 float foamMask = smoothstep(0.42, 0.04, vDepth) * smoothstep(0.15, 0.85, foamWave);
1401:                                 float edgeLine = smoothstep(0.10, 0.0, vDepth);
1402:                                 float foam = clamp(foamMask * 0.75 + edgeLine * 0.85, 0.0, 1.0);
1403:                                 color = mix(color, vec3(0.92, 0.96, 0.98), foam);
1404:                                 alpha = max(alpha, foam * 0.9);
1405:                             }
1406: 
1407:                             // Exponential distance fog integration
1408:                             float fogFactor = 1.0 - exp(-uFogDensity * uFogDensity * vFogDepth * vFogDepth);
1409:                             color = mix(color, uFogColor, clamp(fogFactor, 0.0, 1.0));
1410: 
1411:                             gl_FragColor = vec4(color, alpha);
1412:                         }
1413:                     `
1414:                 });
