2928:             /**
2929:              * 11. Dynamic 24-Hour Solar, Sky, Fog & Water Lighting Cycle
2930:              */
2931:             updateDayNightCycle(dt) {
2932:                 if (this.config.autoCycle && this.isPlaying) {
2933:                     this.config.timeOfDay = (this.config.timeOfDay + dt * 0.16) % 24;
2934:                     document.getElementById('set-time').value = this.config.timeOfDay.toFixed(1);
2935:                 }
2936: 
2937:                 const t = this.config.timeOfDay;
2938:                 const hours = Math.floor(t);
2939:                 const mins = Math.floor((t - hours) * 60);
2940:                 document.getElementById('hud-time').textContent =
2941:                     `${String(hours).padStart(2, '0')}:${String(mins).padStart(2, '0')}`;
2942: 
2943:                 const sunAngle = ((t - 6) / 24) * Math.PI * 2;
2944:                 const sunY = Math.sin(sunAngle);
2945:                 const sunX = Math.cos(sunAngle) * 0.8;
2946:                 const sunZ = 0.45;
2947: 
2948:                 const sunDir = new THREE.Vector3(sunX, sunY, sunZ).normalize();
2949:                 this.sunLight.position.copy(this.dino.position).addScaledVector(sunDir, 75);
2950:                 this.sunLight.target.position.copy(this.dino.position);
2951:                 this.sunLight.target.updateMatrixWorld();
2952: 
2953:                 for (const u of this.sunUniforms) {
2954:                     u.value.copy(sunDir);
2955:                 }
2956:                 if (this.waterUniforms) {
2957:                     this.waterUniforms.uSunDir.value.copy(sunDir);
2958:                 }
2959: 
2960:                 this.skyDome.material.uniforms.sunDirection.value.copy(sunDir);
2961: 
2962:                 const dayFactor = THREE.MathUtils.clamp((sunY + 0.15) / 0.65, 0, 1);
2963:                 const sunsetFactor = Math.exp(-Math.pow((sunY - 0.05) * 5.0, 2));
2964: 
2965:                 const nightTop = new THREE.Color(0x050914);
2966:                 const dayTop = new THREE.Color(0x1b4f8c);
2967:                 const topCol = nightTop.clone().lerp(dayTop, dayFactor);
2968: 
2969:                 const nightBot = new THREE.Color(0x0c1424);
2970:                 const dayBot = new THREE.Color(0xa6cde8);
2971:                 const sunsetBot = new THREE.Color(0xe86c35);
2972:                 const botCol = nightBot.clone().lerp(dayBot, dayFactor).lerp(sunsetBot, sunsetFactor * 0.85);
2973: 
2974:                 this.skyDome.material.uniforms.topColor.value.copy(topCol);
2975:                 this.skyDome.material.uniforms.bottomColor.value.copy(botCol);
2976:                 this.scene.fog.color.copy(botCol);
2977: 
2978:                 const sunDayCol = new THREE.Color(0xfff6e5);
2979:                 const sunSetCol = new THREE.Color(0xff7e3b);
2980:                 this.sunLight.color.copy(sunDayCol).lerp(sunSetCol, sunsetFactor);
2981:                 this.sunLight.intensity = Math.max(0.08, dayFactor * 3.4);
2982:                 this.hemiLight.intensity = (this.dino.scentActive ? 0.55 : 0.20) + dayFactor * 0.48;
2983: 
2984:                 if (this.waterUniforms) {
2985:                     this.waterUniforms.uSunColor.value.copy(this.sunLight.color);
2986:                     this.waterUniforms.uSkyColor.value.copy(botCol);
2987:                     this.waterUniforms.uFogColor.value.copy(botCol);
2988:                 }
2989: 
2990:                 const timeIcon = document.getElementById('time-icon');
2991:                 if (dayFactor > 0.25) {
2992:                     timeIcon.className = 'fas fa-sun text-amber-400';
2993:                 } else {
2994:                     timeIcon.className = 'fas fa-moon text-sky-300';
2995:                 }
2996:             }
