2998:             /**
2999:              * 12. Playable Theropod Movement, Digitigrade Stride Kinematics, Roar & 'The Isle' Camera
3000:              */
3001:             updateTheropodAndCamera(dt) {
3002:                 if (this.isPlaying) {
3003:                     const forward = new THREE.Vector3(-Math.sin(this.dino.camYaw), 0, -Math.cos(this.dino.camYaw));
3004:                     const right = new THREE.Vector3(Math.cos(this.dino.camYaw), 0, -Math.sin(this.dino.camYaw));
3005: 
3006:                     const moveDir = new THREE.Vector3();
3007:                     if (this.keys['KeyW'] || this.keys['ArrowUp']) moveDir.add(forward);
3008:                     if (this.keys['KeyS'] || this.keys['ArrowDown']) moveDir.sub(forward);
3009:                     if (this.keys['KeyD'] || this.keys['ArrowRight']) moveDir.add(right);
3010:                     if (this.keys['KeyA'] || this.keys['ArrowLeft']) moveDir.sub(right);
3011:                     if (moveDir.lengthSq() > 0) moveDir.normalize();
3012: 
3013:                     const wantsSprint = (this.keys['ShiftLeft'] || this.keys['ShiftRight']) && moveDir.lengthSq() > 0 && !this.dino.isCrouching;
3014:                     let targetSpeed = this.dino.isCrouching ? this.dino.crouchSpeed : this.dino.walkSpeed;
3015: 
3016:                     if (wantsSprint && this.dino.stamina > 4) {
3017:                         targetSpeed = this.dino.sprintSpeed;
3018:                         this.dino.stamina = Math.max(0, this.dino.stamina - dt * 22);
3019:                     } else {
3020:                         this.dino.stamina = Math.min(100, this.dino.stamina + dt * 15);
3021:                     }
3022: 
3023:                     // Dynamic FOV boost during sprint
3024:                     const desiredFov = wantsSprint ? this.config.fov + 8 : this.config.fov;
3025:                     if (Math.abs(this.camera.fov - desiredFov) > 0.05) {
3026:                         this.camera.fov = THREE.MathUtils.lerp(this.camera.fov, desiredFov, dt * 8);
3027:                         this.camera.updateProjectionMatrix();
3028:                     }
3029: 
3030:                     // Subtle survival vitals drift
3031:                     this.dino.hunger = Math.max(0, this.dino.hunger - dt * 0.06);
3032:                     this.dino.thirst = Math.max(0, this.dino.thirst - dt * 0.09);
3033: 
3034:                     // Replenish thirst when wading into the river/lake
3035:                     const terrainY = this.getTerrainHeight(this.dino.position.x, this.dino.position.z);
3036:                     if (terrainY < this.waterLevel + 0.15) {
3037:                         this.dino.thirst = Math.min(100, this.dino.thirst + dt * 12);
3038:                     }
3039: 
3040:                     document.getElementById('hud-stamina-bar').style.width = `${this.dino.stamina}%`;
3041:                     document.getElementById('hud-stamina-text').textContent = `${Math.round(this.dino.stamina)}%`;
3042:                     document.getElementById('hud-hunger-bar').style.width = `${this.dino.hunger}%`;
3043:                     document.getElementById('hud-hunger-text').textContent = `${Math.round(this.dino.hunger)}%`;
3044:                     document.getElementById('hud-thirst-bar').style.width = `${this.dino.thirst}%`;
3045:                     document.getElementById('hud-thirst-text').textContent = `${Math.round(this.dino.thirst)}%`;
3046: 
3047:                     // Smooth inertial velocity
3048:                     this.dino.velocity.x = THREE.MathUtils.lerp(this.dino.velocity.x, moveDir.x * targetSpeed, 10 * dt);
3049:                     this.dino.velocity.z = THREE.MathUtils.lerp(this.dino.velocity.z, targetSpeed * moveDir.z, 10 * dt);
3050: 
3051:                     if (this.keys['Space'] && this.dino.isGrounded) {
3052:                         this.dino.velocity.y = this.dino.jumpForce;
3053:                         this.dino.isGrounded = false;
3054:                     }
3055:                     this.dino.velocity.y -= 21.0 * dt;
3056: 
3057:                     this.dino.position.addScaledVector(this.dino.velocity, dt);
3058: 
3059:                     const groundY = this.getTerrainHeight(this.dino.position.x, this.dino.position.z);
3060:                     if (this.dino.position.y <= groundY) {
3061:                         this.dino.position.y = groundY;
3062:                         this.dino.velocity.y = 0;
3063:                         this.dino.isGrounded = true;
3064:                     }
3065:                 }
3066: 
3067:                 // Update Dino Root Position & Smooth Turn Alignment
3068:                 this.dinoRoot.position.copy(this.dino.position);
3069:                 const horizSpeed = Math.hypot(this.dino.velocity.x, this.dino.velocity.z);
3070: 
3071:                 if (horizSpeed > 0.35) {
3072:                     const moveAngle = Math.atan2(-this.dino.velocity.x, -this.dino.velocity.z);
3073:                     let diff = moveAngle - this.dino.bodyYaw;
3074:                     while (diff < -Math.PI) diff += Math.PI * 2;
3075:                     while (diff > Math.PI) diff -= Math.PI * 2;
3076:                     this.dino.bodyYaw += diff * Math.min(1, dt * 8.5);
3077:                 } else if (this.config.cameraMode === 'fp') {
3078:                     this.dino.bodyYaw = this.dino.camYaw;
3079:                 }
3080:                 this.dinoRoot.rotation.y = this.dino.bodyYaw;
3081: 
3082:                 // Update Top Compass Heading
3083:                 const deg = Math.round((((-this.dino.camYaw * 180 / Math.PI) % 360) + 360) % 360);
3084:                 const dirs = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
3085:                 const cardinal = dirs[Math.round(deg / 45) % 8];
3086:                 document.getElementById('compass-heading').textContent = `${cardinal} ${String(deg).padStart(3, '0')}°`;
3087: 
3088:                 // AAA T-Rex Rig Animation + Roar
3089:                 const rig = this.theropodRig;
3090:                 let roarShake = 0;
3091:                 if (this.trexEngine) this.trexEngine.update(this.elapsedTime);
3092: 
3093:                 if (this.dino.roarTimer > 0) {
3094:                     this.dino.roarTimer = Math.max(0, this.dino.roarTimer - dt);
3095:                     const roarCurve = Math.sin((1.45 - this.dino.roarTimer) / 1.45 * Math.PI);
3096:                     if (rig.lowerJaw) rig.lowerJaw.rotation.x = 0.1 + roarCurve * 0.62;
3097:                     if (rig.neck) rig.neck.rotation.x = roarCurve * 0.28;
3098:                     if (rig.head) rig.head.rotation.x = roarCurve * 0.22;
3099:                     roarShake = roarCurve * 0.06 * Math.sin(this.elapsedTime * 48);
3100:                 } else if (rig.lowerJaw) {
3101:                     rig.lowerJaw.rotation.x = THREE.MathUtils.lerp(rig.lowerJaw.rotation.x, 0.1, dt * 10);
3102:                     if (rig.neck) rig.neck.rotation.x = THREE.MathUtils.lerp(rig.neck.rotation.x, 0, dt * 8);
3103:                     if (rig.head) rig.head.rotation.x = THREE.MathUtils.lerp(rig.head.rotation.x, 0, dt * 8);
3104:                 }
3105: 
3106:                 // Primal Sense Light tracking
3107:                 this.primalSenseLight.position.set(this.dino.position.x, this.dino.position.y + 3.0, this.dino.position.z);
3108: 
3109:                 // Camera Positioning ('The Isle' Third-Person Orbital vs First-Person Snout)
3110:                 if (this.config.cameraMode === 'tp') {
3111:                     const pivot = new THREE.Vector3(
3112:                         this.dino.position.x,
3113:                         this.dino.position.y + (this.dino.isCrouching ? 2.0 : 2.6),
3114:                         this.dino.position.z
3115:                     );
3116:                     const dist = 5.6;
3117:                     const offset = new THREE.Vector3(
3118:                         Math.sin(this.dino.camYaw) * Math.cos(this.dino.camPitch) * dist,
3119:                         Math.sin(this.dino.camPitch) * dist + 0.55,
3120:                         Math.cos(this.dino.camYaw) * Math.cos(this.dino.camPitch) * dist
3121:                     );
3122:                     // Slight over-hip offset for cinematic 'The Isle' framing
3123:                     const rightHip = new THREE.Vector3(Math.cos(this.dino.camYaw), 0, -Math.sin(this.dino.camYaw)).multiplyScalar(0.55);
3124:                     const desiredPos = pivot.clone().add(offset).add(rightHip);
3125: 
3126:                     // Prevent camera from clipping below terrain or water surface
3127:                     const minGround = Math.max(this.getTerrainHeight(desiredPos.x, desiredPos.z), this.waterLevel) + 0.45;
3128:                     if (desiredPos.y < minGround) desiredPos.y = minGround;
3129: 
3130:                     this.dino.tpCamPos.lerp(desiredPos, Math.min(1, dt * 14));
3131:                     this.camera.position.copy(this.dino.tpCamPos);
3132:                     this.camera.position.y += roarShake;
3133: 
3134:                     const lookAhead = new THREE.Vector3(-Math.sin(this.dino.camYaw), -Math.sin(this.dino.camPitch) * 0.4, -Math.cos(this.dino.camYaw)).multiplyScalar(4.0);
3135:                     this.camera.lookAt(pivot.clone().add(lookAhead));
