            createNoiseTexture(size, baseHex, detailHex, roughnessMode = false) {
                const canvas = document.createElement('canvas');
                canvas.width = size;
                canvas.height = size;
                const ctx = canvas.getContext('2d');
                ctx.fillStyle = baseHex;
                ctx.fillRect(0, 0, size, size);

                const imgData = ctx.getImageData(0, 0, size, size);
                const data = imgData.data;
                const c1 = new THREE.Color(baseHex);
                const c2 = new THREE.Color(detailHex);

                for (let i = 0; i < data.length; i += 4) {
                    const px = (i / 4) % size;
                    const py = Math.floor((i / 4) / size);
                    const n1 = Math.sin(px * 0.08) * Math.cos(py * 0.08);
                    const n2 = Math.sin(px * 0.35 + py * 0.25) * 0.5;
                    const grain = (Math.random() - 0.5) * 0.35;
                    const blend = THREE.MathUtils.clamp((n1 + n2) * 0.35 + 0.5 + grain, 0, 1);

                    if (roughnessMode) {
                        const val = Math.floor(blend * 255);
                        data[i] = val;
                        data[i + 1] = val;
                        data[i + 2] = val;
                    } else {
                        data[i] = Math.floor(THREE.MathUtils.lerp(c1.r, c2.r, blend) * 255);
                        data[i + 1] = Math.floor(THREE.MathUtils.lerp(c1.g, c2.g, blend) * 255);
                        data[i + 2] = Math.floor(THREE.MathUtils.lerp(c1.b, c2.b, blend) * 255);
                    }
                    data[i + 3] = 255;
                }
                ctx.putImageData(imgData, 0, 0);

                const tex = new THREE.CanvasTexture(canvas);
                tex.wrapS = THREE.RepeatWrapping;
                tex.wrapT = THREE.RepeatWrapping;
                if (!roughnessMode) tex.colorSpace = THREE.SRGBColorSpace;
                return tex;
            }

            createGrassBladeTexture() {
                const canvas = document.createElement('canvas');
                canvas.width = 128;
