                ctx.clearRect(0, 0, 128, 256);

                const drawBlade = (baseX, tipX, height, width) => {
                    const grad = ctx.createLinearGradient(0, 256, 0, 256 - height);
                    grad.addColorStop(0, '#2a421a');
                    grad.addColorStop(0.55, '#4d7328');
                    grad.addColorStop(1, '#8cb846');
                    ctx.fillStyle = grad;
                    ctx.beginPath();
                    ctx.moveTo(baseX - width * 0.5, 256);
                    ctx.quadraticCurveTo(baseX - width * 0.25, 256 - height * 0.55, tipX, 256 - height);
                    ctx.quadraticCurveTo(baseX + width * 0.25, 256 - height * 0.55, baseX + width * 0.5, 256);
                    ctx.closePath();
